/** Collapse runs of whitespace and trim each line. */
export function normalise(text) {
  return text
    .split('\n')
    .map((line) => line.replace(/\s+$/u, ''))
    .join('\n');
}

/** Collapse internal runs of spaces to one. Not yet implemented. */
export function collapseSpaces(text) {
  return text;
}

